-- Read-only permission audit. Never applies migrations, grants, defaults or data changes.
with expected_tables(name)as(values ('account_member_absences'),('account_member_presence'),('account_member_sessions'),('account_members'),('account_settings'),('categories'),('member_completion_totals'),('member_task_completions'),('task_activity_log'),('task_activity_retention_configuration'),('task_coverage_claims'),('task_fine_candidates'),('task_fine_configuration'),('task_fines'),('task_meeting_settings'),('task_member_check_ins'),('task_notification_configuration'),('task_notification_preferences'),('task_notifications'),('task_reopen_requests'),('task_repeat_pending'),('task_retention_configuration'),('task_series'),('task_special_activations'),('task_special_meetings'),('task_special_plans'),('task_templates'),('task_workspaces'),('tasks'),('workspace_invitations')),readable(name)as(values ('account_settings'),('categories'),('task_templates'),('tasks')),
expected_rpc(name)as(values ('task_app_accept_invitation'),('task_app_activity'),('task_app_available_coverage'),('task_app_bin'),('task_app_bin_items'),('task_app_change_role'),('task_app_check_in'),('task_app_check_in_state'),('task_app_clear_notifications'),('task_app_complete_missed'),('task_app_completed'),('task_app_coverage_origins'),('task_app_create_tasks'),('task_app_deleted_templates'),('task_app_fines'),('task_app_invite'),('task_app_leave_member'),('task_app_mark_absent'),('task_app_mark_service_absent'),('task_app_member_history'),('task_app_member_names'),('task_app_member_state'),('task_app_mutate'),('task_app_notification_snapshot'),('task_app_notifications'),('task_app_presence'),('task_app_read_notifications'),('task_app_reassign_all'),('task_app_reassign_permanently'),('task_app_reassign_special'),('task_app_reassignment_preview'),('task_app_release_my_repeats'),('task_app_remove_restriction'),('task_app_remove_template'),('task_app_rename_member'),('task_app_request_reopening'),('task_app_reschedule_special_task'),('task_app_review_reopening'),('task_app_revoke_invitation'),('task_app_save_notification_preferences'),('task_app_save_template'),('task_app_set_special_locked'),('task_app_set_special_meeting_title'),('task_app_settle_fine'),('task_app_setup'),('task_app_special_meeting_title'),('task_app_special_state'),('task_app_take_task'),('task_app_transfer_owner'),('task_app_unmark_absent'),('task_app_unmark_service_absent'),('task_app_workspace_owner'),('task_app_current_member'),('task_app_can_receive_sync')),
tables as(select e.name,c.oid,c.relrowsecurity from expected_tables e left join pg_class c on c.oid=to_regclass('public.'||e.name)),
functions as(select e.name,p.oid,p.prosecdef,p.proconfig from expected_rpc e left join pg_proc p on p.pronamespace='public'::regnamespace and p.proname=e.name),
issues as(
 select 'missing table: '||name issue from tables where oid is null
 union all select 'RLS disabled: '||name from tables where oid is not null and not relrowsecurity
 union all select 'missing authenticated SELECT: '||t.name from tables t join readable r using(name)where not coalesce(has_table_privilege('authenticated',t.oid,'SELECT'),false)
 union all select 'unintended direct SELECT: '||t.name||' / '||r.role from tables t cross join(values('anon'),('authenticated'),('service_role'))r(role)where t.oid is not null and not(r.role='authenticated'and t.name in(select name from readable))and has_any_column_privilege(r.role,t.oid,'SELECT')
 union all select 'direct writes exposed: '||t.name||' / '||r.role from tables t cross join(values('anon'),('authenticated'),('service_role'))r(role)where t.oid is not null and(has_any_column_privilege(r.role,t.oid,'INSERT,UPDATE')or has_table_privilege(r.role,t.oid,'DELETE'))
 union all select 'missing authenticated RPC: '||name from functions where oid is null or not coalesce(has_function_privilege('authenticated',oid,'EXECUTE'),false)
 union all select 'unsafe RPC definition: '||name from functions where oid is not null and(not prosecdef or not coalesce(proconfig @> array['search_path=""'],false))
 union all select 'public or service RPC exposed: '||name from functions where oid is not null and(has_function_privilege('anon',oid,'EXECUTE')or has_function_privilege('service_role',oid,'EXECUTE'))
 union all select 'private helper exposed: '||p.proname from pg_proc p where p.pronamespace='public'::regnamespace and p.proname like 'task_app_%'and p.proname not in(select name from expected_rpc)and(has_function_privilege('anon',p.oid,'EXECUTE')or has_function_privilege('authenticated',p.oid,'EXECUTE')or has_function_privilege('service_role',p.oid,'EXECUTE'))
 union all select 'public schema usage missing'where not has_schema_privilege('authenticated','public','USAGE')
)
select jsonb_build_object(
 'issues',coalesce((select jsonb_agg(issue order by issue)from issues),'[]'::jsonb),
 'app_tables',(select count(*)from tables where oid is not null),
 'required_read_tables',(select count(*)from readable),
 'required_functions',(select count(*)from expected_rpc),
 'table_rls_enabled',(select count(*)from tables where relrowsecurity),
 'authenticated_select_tables',(select jsonb_agg(name order by name)from tables where oid is not null and has_any_column_privilege('authenticated',oid,'SELECT')),
 'public_anon_select_tables',(select count(*)from tables where oid is not null and has_any_column_privilege('anon',oid,'SELECT')),
 'api_public_schemas',current_setting('pgrst.db_schemas',true),
 'public_defaults',coalesce((select jsonb_agg(jsonb_build_object('creator',pg_get_userbyid(d.defaclrole),'kind',d.defaclobjtype,'grantee',pg_get_userbyid(a.grantee),'privilege',a.privilege_type)order by d.defaclrole,d.defaclobjtype,a.grantee,a.privilege_type)from pg_default_acl d cross join lateral aclexplode(d.defaclacl)a where d.defaclnamespace='public'::regnamespace and d.defaclobjtype in('r','S')and a.grantee in('anon'::regrole,'authenticated'::regrole,'service_role'::regrole)),'[]'::jsonb),
 'server_now',clock_timestamp()
)as explicit_grants_audit;
